const Home = () => {
  const API_URL = "https://fakestoreapi.com/products";

  return(
    async function fetchProductData(){
      setLoading(true);
      try{
        const res = await fetch(API_URL);
        const data = res.json();
        setPost(data);

      }
      catch(error){
        console.log("error aaya hai");
      }
      
      setLoading()
    }
  )
};

export default Home;
